/**
 * Skeleton: a placeholder block shown while content loads.
 * Purpose: keeps the layout stable until data arrives. Generated by shadcn, then re-themed to Grove.
 *   Owner: design system.
 * Props: shape ("text" a line of body text | "title" a larger line | "circle" | "image" 4:3 |
 *   "row" a table or list row | "card" a whole card; "block" by default, sized by className),
 *   className sets width and any other size; native div props.
 * Responsive: shapes fill the width of their container unless a width class is given.
 * Accessibility: hidden from screen readers; mark the parent aria-busy while loading. The shimmer
 *   stops under prefers-reduced-motion (globals.css).
 * States: loading only. Dependencies: cva, cn (shimmer in theme.css).
 * Tests: feedback.test.tsx; Design Lab "Feedback" (S2-T07).
 * UX reference: ds-feedback, loading states (c-core.css .sk).
 */
import { cva, type VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

const skeletonStyles = cva("animate-shimmer", {
  variants: {
    shape: {
      block: "rounded-md",
      text: "h-3.5 w-full rounded-sm",
      title: "h-5 w-3/5 rounded-sm",
      circle: "aspect-square rounded-pill",
      image: "aspect-4/3 w-full rounded-lg",
      row: "h-14 w-full rounded-md",
      card: "min-h-64 w-full rounded-xl",
    },
  },
  defaultVariants: { shape: "block" },
});

type SkeletonProps = Omit<ComponentProps<"div">, "ref"> & VariantProps<typeof skeletonStyles>;

function Skeleton({ className, shape, ...props }: SkeletonProps) {
  return (
    <div
      data-slot="skeleton"
      aria-hidden="true"
      className={cn(skeletonStyles({ shape }), className)}
      {...props}
    />
  );
}

export { Skeleton };
